use serde::{Deserialize,Serialize};use thiserror::Error;#[derive(Clone,Copy,Debug,Eq,PartialEq,Serialize,Deserialize)]pub struct HardwareProfile{pub logical_cpus:usize,pub memory_bytes:u64,pub free_disk_bytes:u64,pub apple_silicon:bool}#[derive(Clone,Copy,Debug,Eq,PartialEq,Serialize,Deserialize)]pub struct WorkloadRequest{pub instruments:usize,pub venues:usize,pub orderbook_levels:usize,pub replay:bool,pub option_surface:bool,pub model_host_bytes:u64}#[derive(Clone,Copy,Debug,Eq,PartialEq,Serialize,Deserialize)]pub struct CapacityPlan{pub worker_threads:usize,pub event_channel:usize,pub book_memory_bytes:u64,pub feature_memory_bytes:u64,pub total_memory_bytes:u64,pub admitted:bool}
pub fn plan(h:HardwareProfile,r:WorkloadRequest)->Result<CapacityPlan,CapacityError>{if h.logical_cpus==0||h.memory_bytes<2*1024*1024*1024||r.instruments==0||r.venues==0||r.orderbook_levels==0{return Err(CapacityError::Input)}let books=(r.instruments as u64).checked_mul(r.venues as u64).and_then(|v|v.checked_mul(r.orderbook_levels as u64)).and_then(|v|v.checked_mul(64)).ok_or(CapacityError::Overflow)?;let features=(r.instruments as u64).checked_mul(64*1024*1024).ok_or(CapacityError::Overflow)?;let total=books.checked_add(features).and_then(|v|v.checked_add(r.model_host_bytes)).and_then(|v|v.checked_add(if r.replay{2*1024*1024*1024}else{0})).and_then(|v|v.checked_add(if r.option_surface{1024*1024*1024}else{0})).ok_or(CapacityError::Overflow)?;Ok(CapacityPlan{worker_threads:h.logical_cpus.saturating_sub(1).max(2).min(32),event_channel:(r.instruments*r.venues*128).clamp(1024,1_000_000),book_memory_bytes:books,feature_memory_bytes:features,total_memory_bytes:total,admitted:total<=h.memory_bytes*70/100&&h.free_disk_bytes>=20*1024*1024*1024})}#[derive(Debug,Error)]pub enum CapacityError{#[error("input")]Input,#[error("overflow")]Overflow}
